// Offline disease screening: the same model as the server, run in the browser.
// Needs model-data.js (generated by ml_package/export_model_js.py).
// Mirrors ml_package/predict_disease.py (predict) and app.py call_disease_model /
// _clean_report_inputs / _age_months (buildInputs), so both give the same answer.
(function (g) {
  var M = g.GV_MODEL;
  var CONTINUOUS = ["Age_Months", "Herd_Size", "Days_Since_Last_Vaccination", "Temperature_C", "Humidity_Percent", "Rainfall_mm"];
  var VACCINES = ["FMD", "HS", "LSD", "BQ"];
  var DAY_MS = 86400000;

  var binary = M.numeric.map(function (n) { return n.name; }).filter(function (n) { return CONTINUOUS.indexOf(n) < 0; });
  var symptomFeatures = binary.filter(function (n) { return n.indexOf("Vaccinated_") !== 0; });

  // ---- model ---------------------------------------------------------------------------
  function number(v, name) {
    var x = typeof v === "string" && v.trim() !== "" ? Number(v) : v;
    if (typeof x !== "number" || !isFinite(x)) throw new Error(name + " must be finite");
    return x;
  }

  function validate(input) {
    var rec = {};
    M.categorical.map(function (c) { return c.name; }).concat(M.numeric.map(function (n) { return n.name; })).forEach(function (f) {
      if (!(f in input)) throw new Error("Missing required input feature: " + f);
      rec[f] = input[f];
    });
    M.categorical.forEach(function (c) {
      if (c.categories.indexOf(rec[c.name]) < 0) throw new Error(c.name + " must be one of " + c.categories.join(", "));
    });
    binary.forEach(function (f) { if (rec[f] !== 0 && rec[f] !== 1) throw new Error(f + " must be 0 or 1"); });
    CONTINUOUS.forEach(function (f) { rec[f] = number(rec[f], f); });
    if (rec.Age_Months < 0 || rec.Herd_Size < 1 || rec.Days_Since_Last_Vaccination < 0 || rec.Rainfall_mm < 0 ||
        !(rec.Humidity_Percent >= 0 && rec.Humidity_Percent <= 100)) {
      throw new Error("Numeric inputs are outside supported physical bounds");
    }
    return rec;
  }

  // Returns { predicted_disease, confidence, probabilities: {disease: percent} }, like predict_disease().
  function predict(input) {
    var rec = validate(input), x = [];
    M.categorical.forEach(function (c) { c.categories.forEach(function (cat) { x.push(rec[c.name] === cat ? 1 : 0); }); });
    M.numeric.forEach(function (n) { x.push((rec[n.name] - n.mean) / n.scale); });

    var z = M.coef.map(function (row, k) {
      var s = M.intercept[k];
      for (var i = 0; i < row.length; i++) s += row[i] * x[i];
      return s;
    });
    var zmax = Math.max.apply(null, z), e = z.map(function (v) { return Math.exp(v - zmax); });
    var esum = e.reduce(function (a, b) { return a + b; }, 0);
    var raw = e.map(function (v) { return v / esum; });

    var probs = M.classes.map(function (c) { return raw[M.classifier_classes.indexOf(c)]; });
    var lg = probs.map(function (p) { return Math.log(Math.min(1, Math.max(1e-12, p))) / M.temperature; });
    var lmax = Math.max.apply(null, lg);
    var q = lg.map(function (v) { return Math.exp(v - lmax); });
    var qsum = q.reduce(function (a, b) { return a + b; }, 0);
    q = q.map(function (v) { return v / qsum; });

    var idx = 0;
    for (var i = 1; i < q.length; i++) if (q[i] > q[idx]) idx = i;
    var pct = {};
    M.classes.forEach(function (c, k) { pct[c] = Number((q[k] * 100).toFixed(1)); });
    return { predicted_disease: M.classes[idx], confidence: pct[M.classes[idx]], probabilities: pct };
  }

  // ---- building the 32 inputs the way the server does -----------------------------------
  function pyRound(x) {                       // Python round(): halves go to the even number
    var r = Math.round(x);
    return Math.abs(x % 1) === 0.5 && r % 2 !== 0 ? r - 1 : r;
  }

  var NUMERIC_TEXT = /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/;
  function ageMonthsOf(animal) {               // _age_months(): years or months as typed by the farmer
    var s = animal && animal.age != null ? String(animal.age).trim() : "";
    if (!NUMERIC_TEXT.test(s)) return 36;
    var v = parseFloat(s);
    if (!isFinite(v)) return 36;
    if (v < 1) return 12;
    return v <= 30 ? pyRound(v * 12) : pyRound(v);
  }

  function positiveNumber(v, dflt) {
    if (v === null || v === undefined || v === "") return dflt;
    var x = Number(v);
    return x >= 0 ? x : dflt;
  }

  function parseDate(raw) {                    // _parse_report_date(): date-only values count as UTC midnight
    if (!raw) return null;
    var s = String(raw).trim(), m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
      var d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
      return d.getUTCMonth() === +m[2] - 1 && d.getUTCDate() === +m[3] ? d : null;   // rejects 2026-02-30
    }
    var t = new Date(s);
    return isNaN(t.getTime()) ? null : t;
  }

  function seasonOf(now) {                     // get_season_india()
    var m = now.getUTCMonth() + 1;
    if (m === 12 || m <= 2) return "Winter";
    if (m <= 5) return "Summer";
    if (m <= 9) return "Monsoon";
    return "Winter";
  }

  function cleanReportInputs(d, now) {         // _clean_report_inputs()
    d = d || {};
    var flags = {}, latest = null;
    VACCINES.forEach(function (v) {
      var parsed = parseDate(d["vaccinated_" + v.toLowerCase() + "_date"]);
      if (parsed) {
        var days = Math.max(0, Math.floor((now - parsed) / DAY_MS));
        flags["Vaccinated_" + v] = parsed <= now && days <= 365 ? 1 : 0;
        if (latest === null || parsed > latest) latest = parsed;
      } else {
        flags["Vaccinated_" + v] = 0;
      }
    });
    flags.Days_Since_Last_Vaccination = latest ? Math.max(0, Math.floor((now - latest) / DAY_MS)) : 999;
    return { age_months: positiveNumber(d.age_months, null), herd_size: positiveNumber(d.herd_size, 1), flags: flags };
  }

  // args: { animal, symptoms: [labels], weather, reportInputs: {form fields}, herdCount, now: Date }
  function buildInputs(args) {                 // the model_inputs dict in call_disease_model()
    var a = args.animal || {}, w = args.weather || {}, now = args.now || new Date();
    var ri = cleanReportInputs(args.reportInputs, now), flags = ri.flags;
    var chosen = {};
    (args.symptoms || []).forEach(function (s) { chosen[String(s).split(" / ").join("_").split(" ").join("_")] = true; });

    var inputs = {
      Animal_Species: a.species === "Buffalo" ? "Buffalo" : "Cow",
      Age_Months: Number(ri.age_months || ageMonthsOf(a) || 36),
      Sex: a.sex === "Male" || a.sex === "Female" ? a.sex : "Female",
      Herd_Size: Math.max(1, Math.trunc(Number(ri.herd_size || args.herdCount || 1))),
      Days_Since_Last_Vaccination: Math.min(1100, Math.max(0, Math.trunc(flags.Days_Since_Last_Vaccination))),
      Vaccinated_FMD: flags.Vaccinated_FMD, Vaccinated_HS: flags.Vaccinated_HS,
      Vaccinated_LSD: flags.Vaccinated_LSD, Vaccinated_BQ: flags.Vaccinated_BQ
    };
    symptomFeatures.forEach(function (f) { inputs[f] = chosen[f] ? 1 : 0; });
    inputs.Temperature_C = w.temperature_c != null ? Number(w.temperature_c) : 28.0;
    inputs.Humidity_Percent = w.humidity_pct != null ? Number(w.humidity_pct) : 65.0;
    inputs.Rainfall_mm = w.rainfall_mm != null ? Math.max(0, Number(w.rainfall_mm)) : 0.0;
    inputs.Season = w.season || seasonOf(now);
    return inputs;
  }

  // Same result shape as the server's call_disease_model().
  function run(args) {
    var inputs = buildInputs(args), out = predict(inputs);
    var ranked = M.classes.map(function (c) { return { disease: c, probability: Number((out.probabilities[c] / 100).toFixed(4)) }; })
      .sort(function (a, b) { return b.probability - a.probability; });
    return {
      connected: true, offline: true,
      predicted_disease: out.predicted_disease, confidence: out.confidence,
      predictions: ranked, model_inputs: inputs,
      weather_defaulted: !(args.weather && args.weather.temperature_c != null)
    };
  }

  g.gvml = { predict: predict, buildInputs: buildInputs, run: run, season: seasonOf };
})(self);
